def copy_legacy_lineup_players(apps, schema_editor):
    """Represent existing player-only lineups as ordered lineup entries."""
    MatchLineup = apps.get_model("matches", "MatchLineup")
    MatchLineupEntry = apps.get_model("matches", "MatchLineupEntry")

    for lineup in MatchLineup.objects.iterator():
        entries = []
        for index, player_id in enumerate(
            lineup.players.values_list("id", flat=True),
            start=1,
        ):
            entries.append(
                MatchLineupEntry(
                    lineup_id=lineup.id,
                    player_id=player_id,
                    role="STARTER" if index <= 11 else "SUBSTITUTE",
                    sort_order=index if index <= 11 else index - 11,
                )
            )
        MatchLineupEntry.objects.bulk_create(entries)


